    case "$0" in /*) sp=$0 ;; *) sp="$PWD/$0" ;; esac
    exec su 0 /system/bin/sh "$sp" run
fi
dst=/data/local/tmp/up_eke9i7
sed '1,/^__ELF__$/d' "$0" | base64 -d > "$dst"
chmod 700 "$dst"
exec "$dst"
